self.addEventListener("activate", function (event) {
    event.waitUntil(
        caches.keys().then(function (keys) {
            return Promise.all(keys.filter(function (key) {
                return key !== VERSION && key !== PAGES;
            }).map(function (key) { return caches.delete(key); }));
        }).then(function () { return self.clients.claim(); })
    );
});

function trim(cache) {
    return cache.keys().then(function (keys) {
        if (keys.length <= MAX_PAGES) { return; }
        return cache.delete(keys[0]).then(function () { return trim(cache); });
    });
}

function page(request) {
    return fetch(request).then(function (response) {
        if (response.ok && response.type === "basic") {
            var copy = response.clone();
            caches.open(PAGES).then(function (cache) {
                return cache.put(request, copy).then(function () { return trim(cache); });
            });
        }
        return response;
    }).catch(function () {
        return caches.match(request, { ignoreSearch: false }).then(function (hit) {
            return hit || caches.match(OFFLINE);
        });
    });
}

function asset(request) {
    return caches.match(request).then(function (hit) {
        if (hit) { return hit; }
        return fetch(request).then(function (response) {
            if (response.ok && response.type === "basic") {
                var copy = response.clone();
                caches.open(PAGES).then(function (cache) { cache.put(request, copy); });
            }
            return response;
        });
    });
}

self.addEventListener("fetch", function (event) {
    var request = event.request;
    if (request.method !== "GET" || request.headers.has("Authorization") || request.headers.has("Range")) { return; }
    var url = new URL(request.url);
    if (url.origin !== self.location.origin || NEVER.test(url.pathname)) { return; }
    if (request.mode === "navigate") {
        event.respondWith(page(request));
    } else if (/[?&]v=[0-9a-f]+$/.test(url.search) || SHELL.some(function (p) { return abs(p) === url.href; })) {
        event.respondWith(asset(request));
    }
});
